<script setup>
import { ref, computed, nextTick } from 'vue'
import { useRouter } from 'vue-router'
import Icon from './Icon.vue'
import ProcessCard from './ProcessCard.vue'
import MapGraph from './ontology/MapGraph.vue'
import OntoChangeList from './ontology/OntoChangeList.vue'
import { adminOnce, planGraph } from './ontology/OntoEditCard.vue'
import { api } from '../api.js'
import { narrow } from '../viewport.js'

// A definition generated by process-gpt's bpmn-process-generation-skill, before and after saving.
// 「지도에 넣기」 puts it on the company process map as a process made by words (server: edit/from-draft → Plan, no model; edit/apply;
// the server keeps content.mapPlan · content.mapApplied on the message). 「프로세스로 저장」 still saves it as a proc_def.
const props = defineProps({ msg: Object })
const router = useRouter()
const c = computed(() => props.msg.content)
const pd = computed(() => c.value.contract?.processDefinition || {})
const els = computed(() => pd.value.elements || [])
// elements[] as the agent writes it, or activities[] once completion flattened it (the card reads the
// folder the way saving does: lib/generated.js generatedContract)
const acts = computed(() => (els.value.length ? els.value.filter((e) => e.elementType === 'Activity') : pd.value.activities || []))
const forms = computed(() => c.value.contract?.forms || [])
const agents = computed(() => c.value.contract?.agents || [])
const busy = ref('')
const err = ref('')
const isAgent = (a) => (a.agentMode && a.agentMode !== 'none') || a.orchestration

async function save() {
  busy.value = 'save'
  err.value = ''
  try { await api(`/drafts/${props.msg.id}/save`, { method: 'POST' }) } catch (e) { err.value = '저장하지 못했어요. ' + e.message.slice(0, 120) } finally { busy.value = '' }
}

// ---------- 지도에 넣기 ----------
const fresh = ref(null) // the plan this card asked for (else the one kept on the message)
const plan = computed(() => fresh.value || c.value.mapPlan || null)
const open = ref(!!c.value.mapPlan && !c.value.mapApplied)
const applied = ref(null)
const mapped = computed(() => applied.value || c.value.mapApplied || null)
const admin = ref(null)
adminOnce().then((a) => { admin.value = a })
const ops = computed(() => plan.value?.ops || [])
const canApply = computed(() => !!plan.value && plan.value.canApply !== false && admin.value !== false && ops.value.length > 0)
const whyNot = computed(() => {
  if (canApply.value || !plan.value) return ''
  if (plan.value.whyNot) return plan.value.whyNot
  if (admin.value === false) return '적용은 관리자만 할 수 있어요 — 의견으로 남길 수 있어요'
  return ops.value.length ? '' : '지도에 넣을 것이 없어요.'
})
const graph = computed(() => planGraph(plan.value?.after))
// MapGraph fits the drawing (whole) once it is on the page; a wheel over it scrolls the chat (a pinch still zooms)
const fit = ref(false)
const fitSoon = () => nextTick(() => { fit.value = true })
const passWheel = (e) => { if (!e.ctrlKey) e.stopPropagation() }

async function toMap() {
  busy.value = 'plan'
  err.value = ''
  try {
    const r = await api(`/ontology/edit/from-draft/${encodeURIComponent(props.msg.id)}`, { method: 'POST' })
    fresh.value = r?.plan || r
    open.value = true
  } catch (e) { err.value = '지도로 옮기지 못했어요. ' + e.message.slice(0, 160) } finally { busy.value = '' }
}
async function apply() {
  const p = plan.value
  busy.value = 'apply'
  err.value = ''
  try {
    const r = await api('/ontology/edit/apply', { method: 'POST', body: { words: p.words, ops: p.ops, messageId: props.msg.id } })
    applied.value = { proc: r?.proc || null, refused: r?.refused || [] }
    open.value = false
  } catch (e) { err.value = '지도에 넣지 못했어요. ' + e.message.slice(0, 160) } finally { busy.value = '' }
}
const openMap = () => { const k = mapped.value?.proc?.key; if (k) router.push(`/process-map?proc=${encodeURIComponent(k)}`) }
const previewing = computed(() => !mapped.value && !!plan.value && open.value)
</script>

<template>
  <div class="pdc">
    <ProcessCard v-if="c.defId" :msg="{ ...msg, content: { ...c, name: pd.processDefinitionName, mode: 'view' } }" />
    <div class="draft" :class="{ tail: c.defId, bare: c.defId && !mapped && !previewing }">
      <template v-if="!c.defId">
        <span class="badge">새 프로세스 초안</span>
        <h3 class="serif">{{ pd.processDefinitionName }}</h3>
        <p v-if="pd.description" class="desc">{{ pd.description }}</p>
        <ol class="acts">
          <li v-for="(a, i) in acts" :key="a.id" :style="{ '--i': i }">
            <span class="n">{{ i + 1 }}</span>
            <div><b>{{ a.name }}</b><small><Icon :name="isAgent(a) ? 'panel' : 'hand'" :size="12" /> {{ a.role }}</small></div>
          </li>
        </ol>
        <p class="meta">역할 {{ (pd.roles || []).length }} · 폼 {{ forms.length }}<span v-if="agents.length"> · 에이전트 {{ agents.length }}</span></p>
      </template>

      <!-- 회사 프로세스 지도에 넣었어요 -->
      <div v-if="mapped" class="mapped" data-testid="draft-map-applied" :data-proc="mapped.proc?.key || ''">
        <p><Icon name="check" :size="15" /> 지도에 넣었어요 · 제안 단계로 시작해요</p>
        <small v-if="mapped.refused?.length" class="why">하지 않은 것 · {{ mapped.refused.map((r) => r.why ? `${r.label}(${r.why})` : r.label).join(' · ') }}</small>
        <button v-if="mapped.proc?.key" class="lk press" data-testid="draft-map-open" @click="openMap">지도에서 보기</button>
      </div>
      <!-- 지도에 넣으면 이렇게 돼요 -->
      <div v-else-if="previewing" class="mp" data-testid="draft-map-preview">
        <small class="cap">지도에 넣으면<template v-if="plan.name"> 「{{ plan.name }}」 프로세스로</template> 이렇게 돼요</small>
        <div v-if="graph.tasks.length" class="mini" data-testid="draft-map-graph" @wheel.capture="passWheel">
          <MapGraph :tasks="graph.tasks" :edges="graph.edges" :entries="graph.entries" :dir="narrow ? 'TB' : 'LR'" :whole="fit" @vue:mounted="fitSoon" @vue:unmounted="fit = false" />
        </div>
        <OntoChangeList :plan="plan" />
        <div class="btns">
          <button class="go press" :disabled="!!busy || !canApply" :title="whyNot" data-testid="draft-map-apply" @click="apply">{{ busy === 'apply' ? '넣는 중…' : '적용' }}</button>
          <button class="ghost press" :disabled="!!busy" data-testid="draft-map-stop" @click="open = false">그만두기</button>
        </div>
        <small v-if="whyNot" class="why" data-testid="draft-map-whynot">{{ whyNot }}</small>
      </div>
      <p v-if="busy === 'plan'" class="pend pulse">지도로 옮기는 중…</p>

      <div v-if="(!mapped && !previewing) || !c.defId" class="acts2">
        <button v-if="!mapped && !previewing" class="dark-btn" :class="{ small: c.defId }" :disabled="!!busy" data-testid="draft-map" @click="toMap">지도에 넣기</button>
        <button v-if="!c.defId" class="save-btn press" :disabled="!!busy" @click="save">{{ busy === 'save' ? '저장하는 중…' : '프로세스로 저장' }}</button>
      </div>
      <p v-if="err" class="err">{{ err }}</p>
    </div>
  </div>
</template>

<style scoped>
.pdc { width: 424px; max-width: 100%; display: flex; flex-direction: column; gap: 8px; }
.draft { width: 424px; max-width: 100%; border-radius: 24px; padding: 20px 20px 18px; background: var(--bubble-agent-bg); -webkit-backdrop-filter: blur(50px); backdrop-filter: blur(50px); box-shadow: var(--shadow-card); display: flex; flex-direction: column; gap: 8px; }
/* under a saved definition: only the map part */
.draft.tail { padding: 14px 16px; }
.draft.bare { padding: 0 4px; background: none; -webkit-backdrop-filter: none; backdrop-filter: none; box-shadow: none; }
.badge { font-size: 12px; color: var(--text-secondary); letter-spacing: .04em; }
h3 { margin: 0; font-size: 23px; font-weight: 400; line-height: 1.3; }
.desc { margin: 0; font-size: 14px; line-height: 1.5; color: var(--text-secondary); }
.acts { list-style: none; margin: 6px 0 0; padding: 12px; border-radius: 16px; background: var(--field-bg); display: flex; flex-direction: column; gap: 10px; }
.acts li { display: grid; grid-template-columns: 26px 1fr; gap: 10px; align-items: start; animation: blur-in .4s var(--spring) both; animation-delay: calc(var(--i) * 60ms); }
.n { width: 24px; height: 24px; border-radius: 9999px; display: grid; place-items: center; font-size: 12px; background: var(--ink); color: var(--ink-inverse); }
.acts b { font-weight: 500; font-size: 15px; display: block; }
.acts small { display: flex; align-items: center; gap: 5px; color: var(--text-secondary); font-size: 12.5px; margin-top: 2px; }
.meta { margin: 2px 2px 4px; font-size: 13px; color: var(--text-secondary); }
.acts2 { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.dark-btn.small { height: 36px; padding: 0 16px; font-size: 13.5px; }
:root[data-theme="dark"] .dark-btn { background: #f5f5f7; color: #1d1d1f; }
.save-btn { height: 48px; padding: 0 20px; border-radius: 9999px; font-size: 15px; font-weight: 500; background: var(--field-bg); color: var(--text-primary); }
.save-btn:disabled { opacity: .45; cursor: default; }
.mp { display: flex; flex-direction: column; gap: 8px; padding: 12px; border-radius: 16px; background: var(--cell-bg); min-width: 0; }
.cap { font-size: 12.5px; color: var(--text-secondary); line-height: 1.5; }
.mini { position: relative; height: 220px; border-radius: 14px; background: var(--field-bg); overflow: hidden; }
.btns { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.go { height: 34px; padding: 0 16px; border-radius: 9999px; font-size: 13.5px; font-weight: 600; background: var(--ink); color: var(--ink-inverse); white-space: nowrap; }
.ghost { height: 34px; padding: 0 12px; border-radius: 9999px; font-size: 13.5px; color: var(--text-secondary); white-space: nowrap; }
.go:disabled, .ghost:disabled { opacity: .45; cursor: default; }
.why { font-size: 12.5px; color: var(--text-secondary); line-height: 1.5; }
.mapped { display: flex; flex-direction: column; align-items: flex-start; gap: 4px; }
.mapped p { margin: 0; display: inline-flex; align-items: center; gap: 6px; font-size: 14.5px; line-height: 1.5; }
.lk { font-size: 13.5px; font-weight: 500; color: var(--color-info); }
.pend { margin: 0; font-size: 13px; color: var(--text-secondary); }
.err { color: var(--color-error); font-size: 13px; margin: 0; }
</style>
